SELECT COUNT(*) FROM votes as v, comments as c, posts as p, postLinks as pl, users as u WHERE u.Id = c.UserId AND p.Id = pl.PostId AND p.Id = c.PostId AND u.Id = v.UserId AND v.BountyAmount<=50 AND v.CreationDate>='2010-07-21 00:00:00'::timestamp AND v.CreationDate<='2014-09-14 00:00:00'::timestamp AND c.CreationDate>='2010-07-26 20:21:15'::timestamp AND c.CreationDate<='2014-09-13 01:26:16'::timestamp AND p.Score>=-1 AND p.Score<=19 AND p.CommentCount<=13;